function validate([nums, requests]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 100000)) return 'Each value of nums is an integer from 0 to 10^5.';
  if (!Array.isArray(requests) || requests.length < 1 || requests.length > 100000) return 'requests needs 1 to 10^5 ranges.';
  for (const request of requests) {
    if (!Array.isArray(request) || request.length !== 2) return 'Each request is a pair [start, end].';
    const [start, end] = request;
    if (!Number.isInteger(start) || !Number.isInteger(end) || start < 0 || start > end || end >= nums.length) return 'Each request needs 0 <= start <= end < nums.length.';
  }
  return null;
}

