function maxSumRangeQuery(nums, requests) {
  const MOD = 1000000007;
  const n = nums.length;
  const count = new Array(n + 1).fill(0);

  for (const [start, end] of requests) {
    count[start]++;
    count[end + 1]--;
  }
  for (let i = 1; i < n; i++) {
    count[i] += count[i - 1];
  }
  count.pop();

  count.sort((a, b) => a - b);
  nums.sort((a, b) => a - b);
  let total = 0;
  for (let i = 0; i < n; i++) {
    total = (total + nums[i] * count[i]) % MOD;
  }
  return total;
}

