function maxSumRangeQuery(nums, requests) {
  // Try every arrangement and add up each request directly.
  let best = 0;
  const used = new Array(nums.length).fill(false);
  const order = [];
  const place = () => {
    if (order.length === nums.length) {
      let sum = 0;
      for (const [start, end] of requests) for (let k = start; k <= end; k++) sum += order[k];
      best = Math.max(best, sum);
      return;
    }
    for (let i = 0; i < nums.length; i++) {
      if (used[i]) continue;
      used[i] = true;
      order.push(nums[i]);
      place();
      order.pop();
      used[i] = false;
    }
  };
  place();
  return best % 1000000007;
}

