function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'small' ? int(1, 6) : int(1500, 2000);
  const top = size === 'small' ? [0, 3, 10][int(0, 2)] : 100000;
  const nums = Array.from({ length: n }, () => int(0, top));
  const r = size === 'small' ? int(1, 6) : int(1500, 2000);
  const short = rand() < 0.5;
  const requests = Array.from({ length: r }, () => {
    const start = int(0, n - 1);
    const end = short ? Math.min(n - 1, start + int(0, 3)) : int(start, n - 1);
    return [start, end];
  });
  return [nums, requests];
}
